(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const out = {};
  try {
    // 文件已由 --file-input 塞进「从备份恢复」的文件框
    for (let i = 0; i < 30; i++) {
      await sleep(500);
      if (document.querySelector('.bk-msg') || document.querySelector('.bk-err')) break;
    }
    out.restoreMsg = document.querySelector('.bk-msg')?.textContent || null;
    out.restoreErr = document.querySelector('.bk-err')?.textContent || null;

    // 关掉弹层，进元件库看总数（应该是 21：20 内置 + 备份里带回来的 1 个）
    document.querySelector('.bk-close')?.click();
    await sleep(600);
    [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '元件库')?.click();
    await sleep(2400);
    out.cards = document.querySelectorAll('.lib-card').length;
    const names = [...document.querySelectorAll('.lib-card')].map((c) => c.innerText.split('\n')[0]);
    out.restoredName = names.find((n) => n.includes('备份测试元件')) || null;
    out.sub = document.querySelector('.lib-sub')?.textContent?.trim() || null;
  } catch (e) {
    out.error = String(e && e.message ? e.message : e);
  }
  return JSON.stringify(out);
})()
